import type { TermInput } from "@/lib/schema";

/**
 * Biomarker vocabulary named by the cancer subtype pages (the `biomarkers` arrays in src/data/*-subtypes.ts and the
 * cancers with a `parent`) that had no term or target record: molecular groups, risk scores, resistance mutations,
 * pathology measurements and viral status. Every record says what is measured, how (the assay), what a positive
 * result changes and which cancers it matters in, links `cancers` to the subtype ids that name it, and `related` to
 * the tests and drugs that depend on it. Chinese TL;DRs are exported as `tldrZh` and folded by scripts/fold-zh.ts.
 * Wire up with `import { biomarkerTerms } from "./terms-biomarkers-wave";` and `...biomarkerTerms,` in ALL_INPUTS.
 */
const asOf = "2026-09-17";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
type L = { label: string; url: string };
type T = Omit<TermInput, "kind" | "asOf" | "links" | "category"> & { wikipedia?: string; links?: L[] };
const t = (x: T): TermInput => {
  const links: L[] = [...(x.wikipedia ? [{ label: "Wikipedia", url: x.wikipedia }] : []), ...(x.links ?? [])];
  return { kind: "term", asOf, category: "Biomarkers", ...x, links: links.length ? links : undefined };
};

