/** Chinese TL;DRs for the terms above, folded into src/data/i18n/zh.ts by scripts/fold-zh.ts. */
export const tldrZh: Record<string, string> = {
  "medulloblastoma-molecular-groups": "髓母细胞瘤在显微镜下像一种病，实际上是四种：WNT 型几乎都能治愈，SHH 型取决于年龄和 TP53，第 3 组和第 4 组承担了大部分死亡，因此分子分组如今决定一个孩子接受多少放疗和化疗。",
  "pole-ultramutation": "POLE 基因校对区的致病突变让子宫内膜肿瘤每百万碱基带有数百个突变，却反而拥有所有子宫癌中最好的预后之一，因此发现它可以让患者免于化疗或放疗。",
  "nsmp": "NSMP 是三项阳性检测全部阴性时子宫内膜癌得到的标签：没有 POLE 突变、错配修复完整、p53 正常。它是最大的一组，多为激素驱动、低级别，治疗依据分期、分级和雌激素受体，而不是某个分子标志。",
  "ependymoma-molecular-groups": "室管膜瘤现在按发生部位和分子分组命名：后颅窝 A 组（幼儿，最难治愈，伴 1q 获得更差）、B 组（年龄较大，手术加放疗多可治愈）、幕上 ZFTA 融合型与 YAP1 融合型，以及罕见而凶险的 MYCN 扩增脊髓型；分组决定放疗强度和随访。",
  "sclc-molecular-subtypes": "小细胞肺癌五十年来看似一种病；RNA 分析如今按主导转录因子（ASCL1、NEUROD1、POU2F3，或无主导而呈炎症特征）将其拆分，这些亚型加上 DNA 损伤蛋白 SLFN11，是为这个几乎没有生物标志物的癌症匹配药物的最初线索。",
  "uveal-melanoma-prognostic-markers": "几乎所有眼部黑色素瘤都始于 GNAQ 或 GNA11 突变，这也是皮肤黑色素瘤药物对它无效的原因；决定是否会转移到肝脏的是第二层：3 号染色体丢失伴 BAP1 突变和 2 类基因表达谱意味着高风险，EIF1AX 或 SF3B1 突变和 1 类意味着低风险或延迟风险。",
  "interferon-gamma-signature": "干扰素-γ 特征是一组基因的读数，T 细胞在已经进入肿瘤并作战时会开启这些基因；得分高的肿瘤对 PD-1 药物的应答率在多种癌症中更高，但这个分数尚不够可靠，目前仅用于试验。",
  "ipss-m-ipss-r": "IPSS-R 把骨髓原始细胞、血细胞计数和染色体结果相加，IPSS-M 再加上 31 个基因的突变，将骨髓增生异常综合征患者归入某个风险组，由此决定是观察、用生长因子和低强度药物，还是尽快移植。",
  "sokal-elts-scores": "Sokal 和 ELTS 是从第一次血常规算出的分数：诊断时的年龄、脾脏大小、血小板和原始细胞百分比把慢性髓系白血病分为低、中、高风险，高风险患者更可能一开始就用第二代药物而不是伊马替尼。",
  "flipi": "FLIPI 用五个简单指标（年龄超过 60、III 或 IV 期、超过四个淋巴结区、LDH 升高、血红蛋白低）预测滤泡性淋巴瘤的走向；POD24，即开始化学免疫治疗两年内复发，是危险病例最强的单一信号。",
  "mipi": "MIPI 把年龄、体能状态、LDH 和白细胞计数转换成套细胞淋巴瘤的低、中、高风险标签，加上 Ki-67（MIPI-c）或 TP53 状态后更精准；高风险和 TP53 突变的疾病正是单纯化疗失败、BTK 抑制剂、CAR-T 和试验优先介入的地方。",
  "cll-ipi": "CLL-IPI 在诊断时对五项打分（TP53 缺失或突变、IGHV 未突变、β2 微球蛋白升高、晚期分期、年龄超过 65）来预测首次治疗时间和生存；其中 TP53 和 IGHV 仍会改变药物选择，因为它们决定化学免疫治疗是否还是一个选项。",
  "dipss-mipss70": "骨髓纤维化风险评分决定这个病最大的问题：是否进行干细胞移植。DIPSS 用年龄、血细胞计数、原始细胞和症状，DIPSS-plus 加上染色体、输血和血小板，MIPSS70 再加上标志危险克隆的突变。",
  "ipset-thrombosis": "原发性血小板增多症很少缩短寿命，所以治疗重在预防血栓：IPSET 血栓评分结合年龄超过 60、既往血栓和 JAK2 突变，把患者分为极低、低、中、高风险，只有较高风险组才服用降血小板药物。",
  "li-rads": "LI-RADS 是放射科医生对肝硬化背景下肝结节在增强 CT 或 MRI 上的分级，从 LR-1（肯定良性）到 LR-5（肯定是癌）；LR-5 病灶无需活检即按肝细胞癌治疗，这也是肝癌成为少数可仅凭影像诊断的癌症的原因。",
  "pretext-chic": "PRETEXT 描述儿童肝母细胞瘤在任何治疗前占据肝脏四个区段中的几个，并用字母标注侵入血管、肝外扩展、破裂或转移；在 CHIC 系统中结合年龄和 AFP 水平，它决定谁直接手术、谁先化疗、谁需要移植。",
  "wilms-risk-markers": "肾母细胞瘤十个孩子中有九个能治愈，因此它的标志物是为了决定谁可以少治、谁需要多治：显微镜下的间变细胞、肿瘤 DNA 中 1p 和 16q 缺失或 1q 获得，以及在欧洲体系中术前化疗后残留多少胚芽型肿瘤。",
  "b-all-cytogenetic-risk": "儿童白血病的治疗按一张历经五十年建立的风险表选择：诊断时的年龄和白细胞数（NCI 标准）、原始细胞的染色体模式（有利的 ETV6::RUNX1 和高超二倍体，不利的低二倍体、iAMP21、KMT2A、Ph 阳性和 Ph 样）、脑脊液中是否有白血病细胞，最重要的是第一个月内白血病消失得有多快。",
  "disease-volume-chaarted": "新诊断的转移性激素敏感前列腺癌，治疗计划从一次计数开始：四处或以上骨转移且至少一处在脊柱和骨盆之外，或任何肝、肺转移，即为高瘤负荷（CHAARTED）；高瘤负荷患者在激素治疗上加多西他赛可多活数年，低瘤负荷患者则从前列腺放疗获益更多。",
  "graded-prognostic-assessment": "GPA 是一个积分（年龄、体能状态、脑转移数目、脑外扩散，以及某些癌症的肿瘤突变），用于估计脑转移患者的生存期，从几个月到数年不等；肿瘤科医生据此决定放射外科等积极局部治疗是否值得。",
  "ph-like-all": "Ph 样白血病具有费城染色体阳性白血病的基因表达指纹却没有费城染色体；背后是数十种激酶融合和 JAK 通路病变，查明是哪一种，可以告诉医生是否应在化疗基础上加用伊马替尼类药物或 JAK 抑制剂。",
  "abl1-kinase-domain-mutations": "当 CML 药物失效时，通常是白血病改变了药物结合口袋的形状；对 BCR::ABL1 激酶区测序可以命名突变，而突变的名字告诉医生哪种药还能结合：大多数突变对另一种二代药物有效，但 T315I 只对泊那替尼或阿西米尼有效。",
  "mpn-driver-mutations": "几乎所有真性红细胞增多症和大多数原发性血小板增多症及骨髓纤维化都携带三种突变之一（JAK2 V617F、CALR 或 MPL），它们把生长信号卡在开启状态；发现其中之一可确认这是真正的血液肿瘤而非对其他因素的反应，突变类型和血液中携带的比例则影响血栓和进展风险。",
  "aml-myelodysplasia-related": "八个基因（ASXL1、BCOR、EZH2、RUNX1、SF3B1、SRSF2、STAG2、U2AF1、ZRSR2）在凭空出现的白血病中几乎从不突变，却是从慢性骨髓疾病演变而来的白血病的典型特征；在诊断基因检测中发现其一，即把 AML 归为骨髓增生异常相关型，划入不良风险组并改变化疗方案。",
  "sf3b1-mutation": "SF3B1 是一个剪接基因，它的突变使骨髓生成含铁线粒体堆积的红细胞（环形铁粒幼细胞）；在骨髓增生异常综合征中它定义了一个对罗特西普有应答的低风险贫血亚型，而在 CLL 和眼部黑色素瘤中同一突变的含义不同，多为不利或延迟复发。",
  "del5q": "5 号染色体长臂缺失一段会引起一种独特的低风险骨髓增生异常综合征，典型患者是重度贫血、血小板正常或偏高的老年女性；这是唯一有与其遗传学匹配药物的 MDS，来那度胺让三分之二患者脱离输血，除非同时存在 TP53 突变。",
  "myd88-l265p": "MYD88 的一个字母改变（L265P）让 B 细胞的生存信号永久开启；它见于九成以上的华氏巨球蛋白血症、大多数原发中枢和睾丸淋巴瘤以及一组预后差的 DLBCL，预示 BTK 抑制剂有效，而 CXCR4 的第二个突变则预示药物起效更慢。",
  "cyclin-d1-t11-14": "t(11;14) 易位把 cyclin D1 基因放到抗体基因的加速器旁边，使细胞充满推动分裂的蛋白；cyclin D1 的棕色核染色（加上 SOX11）是确诊套细胞淋巴瘤的方法，而在骨髓瘤中同一易位标志着对维奈克拉有应答的患者。",
  "btki-bcl2i-resistance-mutations": "当伊布替尼类药物在 CLL 中失效时，常见原因是药物结合点的突变（BTK C481S）或紧接其下游的突变（PLCG2）；当维奈克拉失效时，BCL2 G101V 突变松开了它的抓握。每一种都能在疾病明显复发前数月于血液中检出，并各自指向不同的下一个药物。",
  "brca-reversion-mutations": "BRCA 基因断裂的癌症在 PARP 抑制剂或铂类的压力下能自我修复：第二个突变恢复了阅读框，DNA 修复机制重新开启，两类药物都不再有效。回复突变在五分之一到三分之一的耐药病例的血液 ctDNA 中出现，意味着该换用另一类治疗了。",
  "met-exon-14-skipping": "一个剪接位点突变使细胞跳过 MET 基因的第 14 外显子，去掉了受体的关闭开关，MET 因此在细胞表面堆积；它见于约 3% 的肺腺癌，多为老年吸烟者或从不吸烟者，可用卡马替尼、特泊替尼和赛沃替尼这些口服药靶向。",
  "mlh1-promoter-methylation": "当肿瘤丢失了 MLH1 错配修复蛋白，对肿瘤做甲基化检测可以区分两种原因：甲基化关闭了基因意味着散发性癌症，没有甲基化则意味着很可能是遗传性林奇综合征突变，全家都需要检测。",
  "1p19q-codeletion": "1 号和 19 号染色体各丢失一整条臂，加上 IDH 突变，如今就是少突胶质细胞瘤的定义；共缺失的肿瘤生长缓慢，对 PCV 化疗加放疗的应答可持续多年，因此这项检测同时决定诊断和治疗方案。",
  "cdkn2a-homozygous-deletion": "9p21 上 CDKN2A/B 基因两个拷贝全部丢失，去掉了细胞分裂的主要刹车；在 IDH 突变型胶质瘤中仅此一项就使肿瘤成为 4 级，在间皮瘤和黑色素瘤中它标志着侵袭性疾病，相邻的 MTAP 基因通常一同丢失，从而打开了一个新的药物靶点。",
  "pten-loss": "PTEN 是 PI3K/AKT 生长通路的刹车；当肿瘤删除或突变它（表现为染色丢失或测序发现），通路便失去约束。在接受激素治疗的乳腺癌中 PTEN 丢失是让患者符合卡匹色替条件的三种改变之一，在前列腺癌中标志侵袭性疾病，在子宫内膜癌的 NSMP 组中几乎普遍存在。",
  "bap1-loss": "BAP1 是间皮瘤、眼部黑色素瘤和透明细胞肾癌最常丢失的肿瘤抑制基因；活检上核染色的丢失在间皮瘤中可确认为癌而非良性相似病变，标志出一半易转移的眼部黑色素瘤，若为遗传则定义了一个包含这三种肿瘤的家族综合征。",
  "sdh-deficiency": "琥珀酸脱氢酶的丢失（表现为 SDHB 染色阴性）标志着一小类肿瘤（部分胃 GIST、副神经节瘤和嗜铬细胞瘤、一种罕见肾癌），它们常为遗传、发生于年轻人、对伊马替尼无反应且生长缓慢；这项染色是对全家进行胚系检测的触发点。",
  "foxo1-fusion-status": "横纹肌肉瘤过去按外观分类（腺泡型或胚胎型）；现在按 PAX3 或 PAX7 基因是否与 FOXO1 融合分类，因为无论外观如何，融合阳性肿瘤复发率高得多，融合状态与手术分组和分期一起决定治疗强度。",
  "ss18-ssx-fusion": "每一例真正的滑膜肉瘤都携带 18 号染色体 SS18 基因与 X 染色体 SSX 基因的融合；通过 FISH、RNA 测序或新的抗体染色发现它，可确认病理医生原本难以判断的诊断，并标记该肿瘤适用几乎只对这种病有效的 MAGE-A4 和 NY-ESO-1 细胞治疗。",
  "mcpyv-status": "约八成默克尔细胞癌由一种常见皮肤病毒驱动，该病毒把自己缝进了肿瘤 DNA；其余病毒阴性者由阳光驱动，携带巨大的突变负荷。两者都对免疫治疗有反应，在病毒阳性患者中，针对病毒蛋白的血液抗体检测可在治疗后追踪癌症。",
  "hhv8-kshv": "卡波西肉瘤、原发性渗出性淋巴瘤和一种 Castleman 病都由人类疱疹病毒 8 引起；活检上其 LANA-1 蛋白的核染色可确认诊断，血液中的病毒量则追踪它可能引发的危险炎症综合征。",
  "gist-risk-stratification": "胃肠道间质瘤术后是否复发，从病理报告上的三项读出：大小、5 平方毫米视野内有多少细胞在分裂、起源部位（胃比小肠或直肠安全），再加上是否破裂；高风险患者接受三年伊马替尼，其他人则不用。",
  "histological-response-induction": "十周化疗后切除骨肉瘤，病理医生绘制肿瘤有多少已经死亡；90% 或以上坏死（良好反应）预示大多数孩子可治愈，低于 90% 预示复发，但 EURAMOS-1 试验显示，对反应差者堆加更多药物并不能改变这一点。",
  "extranodal-extension": "结外侵犯指淋巴结内的癌细胞突破结囊进入周围脂肪；在头颈癌中它是术后最常把放疗变为同步放化疗的单一发现，在 HPV 阴性疾病中还会提高分期。",
  "depth-of-invasion": "浸润深度是癌症从起始表面向下生长的距离，在病理切片上以毫米计量；在口腔癌中它现在决定 T 分期，超过 4 毫米意味着即使颈部淋巴结看起来干净也要处理，在早期胃癌中它决定内镜切除是否足够。",
  "segmental-chromosomal-aberrations": "在儿童神经母细胞瘤中，染色体损伤的模式如同水晶球：整条染色体增减的肿瘤倾向于消退或治愈，节段断裂（11q 丢失、1p 丢失、17q 获得）或 MYCN 扩增的肿瘤会复发，这一模式把孩子在低、中、高风险治疗之间移动。",
  "urinary-catecholamines": "神经母细胞瘤细胞产生肾上腺素类激素，并把分解产物 VMA 和 HVA 排入尿液；一项简单的尿检在十个孩子中有九个能支持诊断，治疗后下降或随访中上升的水平可在不做扫描的情况下追踪肿瘤。",
  "curie-siopen-score": "神经母细胞瘤会摄取 MIBG，一种去甲肾上腺素的放射性近亲；Curie 和 SIOPEN 评分计数扫描上仍然发亮的身体区域，在最初几轮化疗后评分下降不足，标志着这个孩子不太可能用标准方案治愈。",
  "psa-kinetics": "PSA 上升的速度比它的水平更重要：手术或放疗后倍增时间短于十个月，或去势抵抗期短于九个月，标志出癌症进展迅速、能从更早的激素治疗或 PSMA 扫描获益的男性；而 PSA 密度（PSA 除以前列腺体积）则帮助决定谁根本需要活检。",
  "m-protein-free-light-chains": "骨髓瘤细胞是一个抗体生成细胞的克隆，因此向血液中倾泻同一种抗体，即 M 蛋白；测量它（以及随之而来的游离轻链）是骨髓瘤诊断、疗效深度判断和在症状出现前发现复发的方法。",
};
